(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   储层参数反演 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  深度回归：井点孔隙度真值 + 网络预测（连续值回归）\n   屏 2  多属性融合：振幅/频率/阻抗加权 → 孔隙度\n   屏 3  物理约束：范围约束前后孔隙度场对比 + 异常检查\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    /* 固定种子随机数 */\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    /* -----------------------------------------------------\n       屏 1 · 合成井震数据\n       生成一条井的深度序列：孔隙度真值 + 多属性（与孔隙度相关）。\n       返回 { n, depth, poro(真值), attr: [ [振幅], [频率], [阻抗] ] }\n       ----------------------------------------------------- */\n    var ATTR_NAMES = ['振幅', '频率', '阻抗'];\n    function genWell(n, seed) {\n      var rnd = mulberry32(seed || 20261112);\n      var depth = [], poro = [], aAmp = [], aFreq = [], aImp = [];\n      /* 孔隙度：几段砂体（高孔隙）+ 背景泥岩（低孔隙） */\n      var bodies = [];\n      var nb = 3 + Math.floor(rnd() * 2);\n      for (var i = 0; i < nb; i++) {\n        bodies.push({ c: rnd() * n, r: 4 + rnd() * 8, p: 0.18 + rnd() * 0.15 });\n      }\n      for (var d = 0; d < n; d++) {\n        depth.push(d);\n        var p = 0.04 + rnd() * 0.03; /* 背景泥岩孔隙 */\n        for (var b = 0; b < bodies.length; b++) {\n          var g = Math.exp(-((d - bodies[b].c) * (d - bodies[b].c)) / (2 * bodies[b].r * bodies[b].r));\n          p += bodies[b].p * g;\n        }\n        p = clamp(p, 0.02, 0.4);\n        poro.push(p);\n        /* 属性与孔隙度相关 + 噪声 */\n        aAmp.push(clamp(0.15 + p * 1.1 + (rnd() - 0.5) * 0.08, 0, 0.6));\n        aFreq.push(clamp(0.9 - p * 1.3 + (rnd() - 0.5) * 0.1, 0.2, 1.0));\n        aImp.push(clamp(8.5 - p * 9 + (rnd() - 0.5) * 0.8, 4, 9));\n      }\n      return { n: n, depth: depth, poro: poro, attr: [aAmp, aFreq, aImp] };\n    }\n\n    /* -----------------------------------------------------\n       屏 1 · 深度回归「模型」\n       模拟深度网络从多属性回归孔隙度。\n       weight 越高 → 预测越贴近真值（模拟训练充分）。\n       返回 { pred: FloatArray }\n       ----------------------------------------------------- */\n    function deepRegress(well, weight) {\n      var n = well.n;\n      var pred = new Float64Array(n);\n      var rnd = mulberry32(20261113);\n      for (var d = 0; d < n; d++) {\n        var p = well.poro[d];\n        var noise = (1 - weight) * 0.06 * (rnd() + rnd() - 1);\n        pred[d] = clamp(p + noise + (0.5 - weight) * 0.02, 0.0, 0.45);\n      }\n      return { pred: pred };\n    }\n\n    /* 回归评估：RMSE + 相关系数 */\n    function regEval(well, pred) {\n      var n = well.n;\n      var se = 0;\n      for (var i = 0; i < n; i++) se += (well.poro[i] - pred[i]) * (well.poro[i] - pred[i]);\n      var rmse = Math.sqrt(se / n);\n      /* 相关系数 */\n      var mp = 0, mq = 0;\n      for (var j = 0; j < n; j++) { mp += well.poro[j]; mq += pred[j]; }\n      mp /= n; mq /= n;\n      var cov = 0, vp = 0, vq = 0;\n      for (var k = 0; k < n; k++) { cov += (well.poro[k] - mp) * (pred[k] - mq); vp += (well.poro[k] - mp) * (well.poro[k] - mp); vq += (pred[k] - mq) * (pred[k] - mq); }\n      var corr = cov / (Math.sqrt(vp) * Math.sqrt(vq) + 1e-9);\n      return { rmse: rmse, corr: corr };\n    }\n\n    /* -----------------------------------------------------\n       屏 2 · 多属性融合\n       用振幅/频率/阻抗加权估计孔隙度。权重越均衡，单属性失效时越稳健。\n       ----------------------------------------------------- */\n    function multiFuse(well, wAmp, wFreq, wImp) {\n      var n = well.n;\n      var pred = new Float64Array(n);\n      var total = wAmp + wFreq + wImp + 1e-9;\n      for (var d = 0; d < n; d++) {\n        var a = well.attr[0][d], fr = well.attr[1][d], im = well.attr[2][d];\n        var estA = (a - 0.15) / 1.1;\n        var estF = (0.9 - fr) / 1.3;\n        var estI = (8.5 - im) / 9;\n        pred[d] = clamp((estA * wAmp + estF * wFreq + estI * wImp) / total, 0, 0.45);\n      }\n      return { pred: pred };\n    }\n\n    /* 多属性融合评估：用单属性偏差模拟噪声属性 */\n    function fuseEval(well, pred) {\n      var n = well.n;\n      var se = 0;\n      for (var i = 0; i < n; i++) se += (well.poro[i] - pred[i]) * (well.poro[i] - pred[i]);\n      return { rmse: Math.sqrt(se / n) };\n    }\n\n    /* -----------------------------------------------------\n       屏 3 · 物理约束\n       对预测做孔隙度范围约束（lo..hi），并统计越界像素。\n       ----------------------------------------------------- */\n    function physConstrain(pred, lo, hi) {\n      var n = pred.length;\n      var out = new Float64Array(n);\n      var outOfRange = 0;\n      for (var i = 0; i < n; i++) {\n        var v = pred[i];\n        if (v < lo) { v = lo; outOfRange++; }\n        if (v > hi) { v = hi; outOfRange++; }\n        out[i] = v;\n      }\n      return { out: out, outOfRange: outOfRange, lo: lo, hi: hi };\n    }\n\n    /* 屏 3 用：合成二维孔隙度场（含异常） */\n    function genPoroField(W, H, seed) {\n      var rnd = mulberry32(seed || 20261114);\n      var f = new Float64Array(W * H);\n      var y, x;\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var body = Math.exp(-((x - W * 0.5) * (x - W * 0.5)) / 600 - ((y - H * 0.5) * (y - H * 0.5)) / 400) * 0.18;\n          var base = 0.06 + body;\n          f[y * W + x] = clamp(base + (rnd() - 0.5) * 0.04, 0.0, 0.5);\n        }\n      }\n      return { W: W, H: H, f: f };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32,\n      ATTR_NAMES: ATTR_NAMES,\n      genWell: genWell, deepRegress: deepRegress, regEval: regEval,\n      multiFuse: multiFuse, fuseEval: fuseEval,\n      physConstrain: physConstrain, genPoroField: genPoroField\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  /* 全局 UI 状态 */\n  var regState = { weight: 0.6, nWell: 40 };\n  var fuseState = { wAmp: 0.5, wFreq: 0.3, wImp: 0.2 };\n  var physState = { lo: 0.02, hi: 0.35 };\n\n  /* 桥接：给算法解剖动画用同一份真代码 */\n  global.RemoteBridge = {\n    M: M,\n    genWell: M.genWell, deepRegress: M.deepRegress, regEval: M.regEval,\n    multiFuse: M.multiFuse, fuseEval: M.fuseEval,\n    physConstrain: M.physConstrain, genPoroField: M.genPoroField,\n    live: function () {\n      return { weight: regState.weight, nWell: regState.nWell, wAmp: fuseState.wAmp, wFreq: fuseState.wFreq, wImp: fuseState.wImp, lo: physState.lo, hi: physState.hi };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  /* 固定井 */\n  var well1 = M.genWell(60, 20261112);\n  var reg1 = M.deepRegress(well1, regState.weight);\n\n  /* ---------- 屏 1 渲染：深度回归 ---------- */\n  function renderReg() {\n    well1 = M.genWell(60, 20261112);\n    reg1 = M.deepRegress(well1, regState.weight);\n    var ev = M.regEval(well1, reg1.pred);\n    var n = well1.n;\n    var H = 240, W = 360, x0 = 60, y0 = 20, xScale = W / n, yScale = 220 / 0.45;\n\n    /* 坐标轴 */\n    var s = '<line x1=\"' + x0 + '\" y1=\"' + y0 + '\" x2=\"' + x0 + '\" y2=\"' + (y0 + H) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + H) + '\" x2=\"' + (x0 + W) + '\" y2=\"' + (y0 + H) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<text x=\"' + (x0 - 40) + '\" y=\"' + (y0 + 10) + '\" font-size=\"9\" fill=\"#79828a\">孔隙度<\/text>';\n    s += '<text x=\"' + (x0 + W - 60) + '\" y=\"' + (y0 + H + 16) + '\" font-size=\"9\" fill=\"#79828a\">井深（采样点）<\/text>';\n\n    /* 真值（绿线） */\n    var gPath = 'M';\n    for (var i = 0; i < n; i++) gPath += (x0 + i * xScale).toFixed(1) + ' ' + (y0 + H - well1.poro[i] * yScale).toFixed(1) + (i === 0 ? '' : ' L');\n    s += '<path d=\"' + gPath + '\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"2\"/>';\n    s += '<text x=\"' + (x0 + W + 10) + '\" y=\"' + (y0 + 20) + '\" font-size=\"9\" fill=\"#2f7d6b\" font-weight=\"700\">井孔隙度真值<\/text>';\n\n    /* 预测（红线） */\n    var pPath = 'M';\n    for (var j = 0; j < n; j++) pPath += (x0 + j * xScale).toFixed(1) + ' ' + (y0 + H - reg1.pred[j] * yScale).toFixed(1) + (j === 0 ? '' : ' L');\n    s += '<path d=\"' + pPath + '\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"1.8\" stroke-dasharray=\"5 3\"/>';\n    s += '<text x=\"' + (x0 + W + 10) + '\" y=\"' + (y0 + 36) + '\" font-size=\"9\" fill=\"#b26a39\" font-weight=\"700\">网络预测<\/text>';\n    $('regChart').innerHTML = s;\n\n    $('roRmse').textContent = 'RMSE ' + num(ev.rmse, 3);\n    $('roCorr').textContent = '相关系数 ' + num(ev.corr, 2);\n  }\n\n  /* ---------- 屏 2 渲染：多属性融合 ---------- */\n  function renderFuse() {\n    var fuse = M.multiFuse(well1, fuseState.wAmp, fuseState.wFreq, fuseState.wImp);\n    var ev = M.fuseEval(well1, fuse.pred);\n    var n = well1.n;\n    var H = 240, W = 360, x0 = 60, y0 = 20, xScale = W / n, yScale = 220 / 0.45;\n    var s = '<line x1=\"' + x0 + '\" y1=\"' + y0 + '\" x2=\"' + x0 + '\" y2=\"' + (y0 + H) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + H) + '\" x2=\"' + (x0 + W) + '\" y2=\"' + (y0 + H) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    var gPath = 'M';\n    for (var i = 0; i < n; i++) gPath += (x0 + i * xScale).toFixed(1) + ' ' + (y0 + H - well1.poro[i] * yScale).toFixed(1) + (i === 0 ? '' : ' L');\n    s += '<path d=\"' + gPath + '\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"2\"/>';\n    var pPath = 'M';\n    for (var j = 0; j < n; j++) pPath += (x0 + j * xScale).toFixed(1) + ' ' + (y0 + H - fuse.pred[j] * yScale).toFixed(1) + (j === 0 ? '' : ' L');\n    s += '<path d=\"' + pPath + '\" fill=\"none\" stroke=\"#41699b\" stroke-width=\"1.8\" stroke-dasharray=\"5 3\"/>';\n    $('fuseChart').innerHTML = s;\n    $('roFuseRmse').textContent = 'RMSE ' + num(ev.rmse, 3);\n  }\n\n  /* ---------- 屏 3 渲染：物理约束 ---------- */\n  var field = M.genPoroField(56, 40, 20261114);\n  function renderPhys() {\n    /* 原始场（可能超出范围） */\n    var sRaw = '';\n    for (var y = 0; y < field.H; y++) {\n      for (var x = 0; x < field.W; x++) {\n        var v = field.f[y * field.W + x];\n        var g = Math.round(80 + 175 * clamp(v / 0.45, 0, 1));\n        sRaw += '<rect x=\"' + (x * 6) + '\" y=\"' + (y * 6) + '\" width=\"6\" height=\"6\" fill=\"rgb(' + g + ',' + (230 - g * 0.7) + ',120)\"/>';\n      }\n    }\n    /* 越界标记 */\n    for (var y2 = 0; y2 < field.H; y2++) {\n      for (var x2 = 0; x2 < field.W; x2++) {\n        var v2 = field.f[y2 * field.W + x2];\n        if (v2 > physState.hi) sRaw += '<rect x=\"' + (x2 * 6) + '\" y=\"' + (y2 * 6) + '\" width=\"6\" height=\"6\" fill=\"none\" stroke=\"#b05a51\" stroke-width=\"1.2\"/>';\n        if (v2 < physState.lo) sRaw += '<rect x=\"' + (x2 * 6) + '\" y=\"' + (y2 * 6) + '\" width=\"6\" height=\"6\" fill=\"none\" stroke=\"#b05a51\" stroke-width=\"1.2\"/>';\n      }\n    }\n    $('physRaw').innerHTML = sRaw;\n\n    /* 约束后 */\n    var pc = M.physConstrain(field.f, physState.lo, physState.hi);\n    var sC = '';\n    for (var y3 = 0; y3 < field.H; y3++) {\n      for (var x3 = 0; x3 < field.W; x3++) {\n        var v3 = pc.out[y3 * field.W + x3];\n        var g3 = Math.round(80 + 175 * clamp(v3 / 0.45, 0, 1));\n        sC += '<rect x=\"' + (x3 * 6) + '\" y=\"' + (y3 * 6) + '\" width=\"6\" height=\"6\" fill=\"rgb(' + g3 + ',' + (230 - g3 * 0.7) + ',120)\"/>';\n      }\n    }\n    $('physCon').innerHTML = sC;\n    $('roOutRange').textContent = pc.outOfRange + ' 个越界像素被校正';\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inWeight = $('inWeight');\n    if (inWeight) inWeight.addEventListener('input', function () {\n      regState.weight = parseFloat(inWeight.value);\n      $('outWeight').textContent = num(regState.weight, 2);\n      renderReg();\n    });\n    var inAmp = $('inAmp');\n    if (inAmp) inAmp.addEventListener('input', function () {\n      fuseState.wAmp = parseFloat(inAmp.value);\n      $('outAmp').textContent = num(fuseState.wAmp, 2);\n      renderFuse();\n    });\n    var inFreq = $('inFreq');\n    if (inFreq) inFreq.addEventListener('input', function () {\n      fuseState.wFreq = parseFloat(inFreq.value);\n      $('outFreq').textContent = num(fuseState.wFreq, 2);\n      renderFuse();\n    });\n    var inImp = $('inImp');\n    if (inImp) inImp.addEventListener('input', function () {\n      fuseState.wImp = parseFloat(inImp.value);\n      $('outImp').textContent = num(fuseState.wImp, 2);\n      renderFuse();\n    });\n    var inHi = $('inHi');\n    if (inHi) inHi.addEventListener('input', function () {\n      physState.hi = parseFloat(inHi.value);\n      $('outHi').textContent = num(physState.hi, 2);\n      renderPhys();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '深度回归', 'regCtl'], ['sec2', '多属性融合', 'fuseCtl'], ['sec3', '物理约束', 'physCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      el.querySelectorAll('input, button').forEach(function (c) {\n        if (c.type === 'range') c.setAttribute('value', c.value);\n      });\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderReg(); renderFuse(); renderPhys();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   储层参数反演 · 算法解剖（深度回归 + 多属性融合 + 物理约束）\n   ---------------------------------------------------------\n   把「地震属性 → 孔隙度」拆成 6 步，每一步都跑真代码：\n\n     ① 属性与对齐     地震体 → 多属性 + 井震对齐\n     ② 井点标签       测井参数 → 回归标签\n     ③ 深度回归       多属性 → 孔隙度（非线性映射）\n     ④ 多属性融合     振幅/频率/阻抗加权\n     ⑤ 物理约束       范围 + 一致性 → 惩罚不可信\n     ⑥ 复核与部署     井点吻合 → 储层建模 + 回流\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function ease(t) { return t * t * (3 - 2 * t); }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  var N = 60, H = 200, x0 = 40, y0 = 150, W = 360, xS = W / N, yS = 180 / 0.45;\n\n  function linePath(well, arr, x0, y0, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < N; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 + H - arr[i] * yS).toFixed(1);\n      if (i < N - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.weight, L.nWell, L.wAmp, L.wFreq, L.wImp, L.lo, L.hi].join(',');\n    if (cache.key === key) return cache;\n    var well = M.genWell(N, 20261112);\n    var reg = M.deepRegress(well, L.weight);\n    var re = M.regEval(well, reg.pred);\n    var fuse = M.multiFuse(well, L.wAmp, L.wFreq, L.wImp);\n    var fe = M.fuseEval(well, fuse.pred);\n    var field = M.genPoroField(56, 40, 20261114);\n    var phys = M.physConstrain(field.f, L.lo, L.hi);\n    cache = { key: key, L: L, well: well, reg: reg, re: re, fuse: fuse, fe: fe, field: field, phys: phys };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 属性与对齐\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), well = c.well, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 地震体', '多属性提取', C.jade);\n    s += G.panel(1, '② 井点参数', '沿井轨迹投影', C.blue);\n    s += G.panel(2, '③ 对齐网格', '统一采样', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 三条属性曲线 */\n    var attrs = [\n      { name: '振幅', arr: well.attr[0], c: '#41699b' },\n      { name: '频率', arr: well.attr[1], c: '#8a4f27' },\n      { name: '阻抗', arr: well.attr[2], c: '#6b7a6b' }\n    ];\n    for (var a = 0; a < 3; a++) {\n      var ay = y0 + a * 52;\n      s += G.axes(x0, ay, 300, 42, { nx: 3, ny: 1 });\n      s += linePath(well, attrs[a].arr, x0, ay, attrs[a].c, true);\n      s += G.txt(x0 + 310, ay + 20, attrs[a].name, { size: 8.5, fill: attrs[a].c, weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '地震多属性（振幅/频率/阻抗）+ 井震对齐', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(400, 190, 130, 176, '为什么对齐难',\n      ['· 测井是厘米级分辨率',\n       '· 地震是十米级分辨率',\n       '· 直接对齐会错位',\n       '· 需在特征层对齐',\n       '',\n       '对齐错位 → 模型学到',\n       '「错位的假映射」。'], 'clay');\n\n    s += G.txt(x0, y0 + 170, '井震尺度不匹配：测井厘米级 vs 地震十米级 · 必须特征层对齐', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '属性', v: '振幅/频率/阻抗' }, { k: '井', v: L.nWell + ' 口' }, { k: '对齐', v: '特征层' }], note: '第一步把地震体提成多属性，并把井点参数沿井轨迹投影对齐。井震尺度不匹配直接对齐会错位，必须在特征层对齐，否则模型学到错位的假映射。' };\n  }\n\n  /* =========================================================\n     ② 井点标签\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), well = c.well, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 测井解释', '孔隙度/饱和度', C.clay);\n    s += G.panel(1, '② 回归标签', '连续值真值', C.jade);\n    s += G.panel(2, '③ 验证井', '独立评测', C.blue);\n\n    var x0 = 30, y0 = 130;\n    s += G.axes(x0, y0, 360, 180, { nx: 4, ny: 3 });\n    s += linePath(well, well.poro, x0, y0, '#2f7d6b', false);\n    s += G.txt(x0, y0 - 12, '井孔隙度真值（回归标签）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '标签从哪来',\n      ['· 井点测井解释孔隙度',\n       '· 整理成连续回归标签',\n       '· 留出独立验证井',\n       '',\n       '只有 20—50 口井，',\n       '标签稀缺且带解释误差。'], 'clay');\n\n    s += G.txt(x0, y0 + 190, '井标签带解释误差，直接把误差学进映射会偏离井点真值', { size: 9, fill: '#8a4f27' });\n    return { svg: s, stats: [{ k: '井数', v: L.nWell + ' 口' }, { k: '标签', v: '孔隙度连续值' }, { k: '验证', v: '独立井' }], note: '井点测井解释孔隙度整理成连续回归标签，留独立验证井。井标签带解释误差，直接把误差学进映射会让井点预测偏离真值。' };\n  }\n\n  /* =========================================================\n     ③ 深度回归\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), well = c.well, reg = c.reg, re = c.re, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 输入层', '多属性向量', C.blue);\n    s += G.panel(1, '② 隐层', '非线性映射', C.jade);\n    s += G.panel(2, '③ 输出', '孔隙度', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 网络结构 */\n    var layers = [\n      { x: x0, y: y0 + 20, w: 120, h: 120, c: C.blueL, label: '多属性输入' },\n      { x: x0 + 140, y: y0 + 40, w: 90, h: 80, c: C.jadeL, label: '隐层 1' },\n      { x: x0 + 250, y: y0 + 40, w: 90, h: 80, c: C.jadeL, label: '隐层 2' },\n      { x: x0 + 360, y: y0 + 55, w: 90, h: 50, c: C.clayL, label: '孔隙度' }\n    ];\n    for (var i = 0; i < layers.length; i++) {\n      var lx = layers[i].x, ly = layers[i].y;\n      s += G.rect(lx, ly, layers[i].w, layers[i].h, { r: 8, fill: layers[i].c, stroke: i === 0 ? '#9fb5cf' : i === 3 ? '#d8a48c' : '#a7c6b8' });\n      s += G.txt(lx + layers[i].w / 2, ly + layers[i].h / 2, layers[i].label, { size: 8.5, fill: C.ink2, anchor: 'middle' });\n      if (i > 0) s += G.line(lx - 12, ly + layers[i].h / 2, lx - 4, ly + layers[i].h / 2, { stroke: '#9ba3a9', sw: 1 });\n    }\n\n    /* 右：拟合曲线 */\n    var rx = x0 + 470, ry = y0;\n    s += G.axes(rx, ry, 130, 150, { nx: 2, ny: 2 });\n    s += '<path d=\"M' + (rx + 10) + ' ' + (ry + 30) + ' C' + (rx + 40) + ' ' + (ry + 60) + ' ' + (rx + 60) + ' ' + (ry + 80) + ' ' + (rx + 110) + ' ' + (ry + 120) + '\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"2\"/>';\n    s += '<path d=\"M' + (rx + 10) + ' ' + (ry + 36) + ' C' + (rx + 40) + ' ' + (ry + 64) + ' ' + (rx + 60) + ' ' + (ry + 76) + ' ' + (rx + 110) + ' ' + (ry + 122) + '\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\"/>';\n    s += G.txt(rx + 10, ry - 8, '拟合：RMSE ' + f(re.rmse, 3), { size: 8.5, fill: C.ink3 });\n\n    return { svg: s, stats: [{ k: 'RMSE', v: f(re.rmse, 3) }, { k: '相关系数', v: f(re.corr, 2) }], note: '深度回归建立多属性到孔隙度的非线性映射，替代迭代反演。井样本只有 20—50 口，网络太深会过拟合——井点拟合好但井间乱跳。' };\n  }\n\n  /* =========================================================\n     ④ 多属性融合\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), well = c.well, fuse = c.fuse, fe = c.fe, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 单属性估计', '各有偏差', C.blue);\n    s += G.panel(1, '② 自适应加权', '学权重', C.jade);\n    s += G.panel(2, '③ 融合预测', '更稳健', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 三条属性单独估计 vs 融合 */\n    var ests = [\n      { name: '振幅', arr: well.attr[0].map(function (a) { return clamp((a - 0.15) / 1.1, 0, 0.45); }), c: '#41699b' },\n      { name: '频率', arr: well.attr[1].map(function (fr) { return clamp((0.9 - fr) / 1.3, 0, 0.45); }), c: '#8a4f27' },\n      { name: '阻抗', arr: well.attr[2].map(function (im) { return clamp((8.5 - im) / 9, 0, 0.45); }), c: '#6b7a6b' }\n    ];\n    for (var a = 0; a < 3; a++) {\n      var ay = y0 + a * 52;\n      s += G.axes(x0, ay, 300, 42, { nx: 3, ny: 1 });\n      s += linePath(well, ests[a].arr, x0, ay, ests[a].c, true);\n      s += G.txt(x0 + 310, ay + 20, ests[a].name + ' 单独估计', { size: 8.5, fill: ests[a].c, weight: 700 });\n    }\n\n    s += footBox(400, 190, 130, 176, '为什么融合',\n      ['· 单属性各有噪声与偏差',\n       '· 振幅对薄层、频率对岩性',\n       '· 加权融合取长补短',\n       '· 权重由网络自适应学习',\n       '',\n       '权重 ' + f(L.wAmp, 2) + ':' + f(L.wFreq, 2) + ':' + f(L.wImp, 2),\n       'RMSE ' + f(fe.rmse, 3) + ' 比单属性更稳。'], 'jade');\n\n    s += G.txt(x0, y0 + 170, '融合后 RMSE ' + f(fe.rmse, 3) + ' · 单属性失效时仍能靠其它属性兜底', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '权重', v: f(L.wAmp, 2) + ':' + f(L.wFreq, 2) + ':' + f(L.wImp, 2) }, { k: 'RMSE', v: f(fe.rmse, 3) }], note: '单属性各有噪声与偏差，多属性加权融合取长补短，权重由网络自适应学习。简单拼接而不学权重，噪声属性反而拉低精度。' };\n  }\n\n  /* =========================================================\n     ⑤ 物理约束\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), phys = c.phys, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 原始输出', '可能越界', C.clay);\n    s += G.panel(1, '② 物理约束', '范围+一致性', C.blue);\n    s += G.panel(2, '③ 可信场', '符合物理', C.jade);\n\n    var x0 = 30, y0 = 130, cell = 6;\n    var W = 56, H = 40;\n    /* 原始场（含越界红框） */\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        var v = c.field.f[y * W + x];\n        var g = Math.round(80 + 175 * clamp(v / 0.45, 0, 1));\n        s += G.rect(x0 + x * cell, y0 + y * cell, cell, cell, { fill: 'rgb(' + g + ',' + Math.round(230 - g * 0.7) + ',120)', op: 1 });\n        if (v > L.hi || v < L.lo) s += G.rect(x0 + x * cell, y0 + y * cell, cell, cell, { fill: 'none', stroke: '#b05a51', sw: 1.2 });\n      }\n    }\n    s += G.txt(x0, y0 - 12, '原始孔隙度场（红框 = 越界）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    /* 约束后 */\n    var x1 = 320, y1 = 130;\n    for (var y2 = 0; y2 < H; y2++) {\n      for (var x2 = 0; x2 < W; x2++) {\n        var v2 = phys.out[y2 * W + x2];\n        var g2 = Math.round(80 + 175 * clamp(v2 / 0.45, 0, 1));\n        s += G.rect(x1 + x2 * cell, y1 + y2 * cell, cell, cell, { fill: 'rgb(' + g2 + ',' + Math.round(230 - g2 * 0.7) + ',120)', op: 1 });\n      }\n    }\n    s += G.txt(x1, y1 - 12, '物理约束后（' + phys.outOfRange + ' 个越界校正）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += G.txt(x0, y0 + 200, '约束范围 ' + f(L.lo, 2) + '—' + f(L.hi, 2) + ' · 越界像素 ' + phys.outOfRange, { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '越界', v: phys.outOfRange }, { k: '约束', v: f(L.lo, 2) + '—' + f(L.hi, 2) }], note: '纯回归可能输出「看似合理但违反地质」的参数（孔隙度为负、超范围）。物理约束把范围与岩性一致性加进损失，惩罚越界，得到可信孔隙度场。' };\n  }\n\n  /* =========================================================\n     ⑥ 复核与部署\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), re = c.re, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 井点吻合', 'RMSE 检查', C.blue);\n    s += G.panel(1, '② 异常复查', '物理不可信区', C.clay);\n    s += G.panel(2, '③ 储层建模', '井位部署+回流', C.jade);\n\n    var x0 = 30, y0 = 130;\n    /* 井点吻合表 */\n    var rows = [\n      ['井 A', '吻合 0.012', 'ok'],\n      ['井 B', '吻合 0.009', 'ok'],\n      ['井 C', '异常 0.031', '复查'],\n      ['井 D', '吻合 0.011', 'ok'],\n      ['井 E', '异常 0.028', '复查']\n    ];\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 26;\n      s += G.rect(x0, ry, 360, 22, { r: 4, fill: rows[r][2] === 'ok' ? C.jadeL : C.clayL, stroke: rows[r][2] === 'ok' ? '#b9d8cb' : '#e6cdb2' });\n      s += G.txt(x0 + 12, ry + 15, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(x0 + 90, ry + 15, rows[r][1], { size: 8.8, fill: rows[r][2] === 'ok' ? C.jadeD : '#8a4f27' });\n      s += G.txt(x0 + 320, ry + 15, rows[r][2], { size: 8.8, fill: rows[r][2] === 'ok' ? C.jadeD : '#8a4f27', weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '井点吻合与异常复查清单', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '人在环的价值',\n      ['· 人只处理异常井与异常区',\n       '· 局部修正后确认孔隙度场',\n       '· 进入储层建模与井位部署',\n       '· 错误反馈回训练集',\n       '',\n       '整体 RMSE ' + f(re.rmse, 3),\n       '无人在环 → 不可信场扩散。'], 'clay');\n\n    s += G.txt(x0, y0 + 150, '产出：物理可信的孔隙度场 + 井点吻合 + 置信度 → 储层建模', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: 'RMSE', v: f(re.rmse, 3) }, { k: '产出', v: '孔隙度场' }], note: '地质师对井点吻合与异常区复查，局部修正后孔隙度场进入储层建模与井位部署。错误反馈回训练集，模型持续改进。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：储层参数反演<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n/* 右侧控件抽屉（嵌入主站时由父页面接管，这里保留独立样式兜底） */\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 物探解释 / 储层参数反演<\/span>\n  <h1>从「迭代反演 · 多解性强」到「深度回归代理 · 秒级出孔隙度场」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂深度回归、Q2 多属性融合、Q3 物理约束。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 反演全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「属性 → 黑盒 → 孔隙度」，而是<b>逐段展开<\/b>：属性对齐 → 井点标签 → 深度回归 → 多属性融合 → 物理约束 → 复核部署，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 3—5<\/span>\n    <h2>把「地震属性 → 孔隙度」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改回归权重、属性融合权重和物理约束上限，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（回归拟合、融合预测、约束前后孔隙度场）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>deepRegress / multiFuse / physConstrain<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 3 步用网络结构示意「多属性 → 隐层 → 孔隙度」的非线性映射；<b>②<\/b> 第 5 步把原始场与约束后场并排放，看得见「物理约束怎么把不可信值校正回范围」。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 深度回归 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">常规反演流程长、多解性强；深度回归代理一次前向就出孔隙度<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 3<\/span>\n    <h2>深度回归：把地震属性映射到孔隙度连续值<\/h2>\n    <p class=\"leadline\">拖回归权重，看网络预测曲线与井真值的差距——这就是「多属性 → 孔隙度」非线性映射的核心。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"regCtl\">\n    <div class=\"sl\">\n      <label>回归权重<output id=\"outWeight\">0.60<\/output><\/label>\n      <input type=\"range\" id=\"inWeight\" min=\"0\" max=\"1.4\" step=\"0.05\" value=\"0.6\">\n    <\/div>\n  <\/div>\n  <svg id=\"regChart\" viewBox=\"0 0 470 280\" role=\"img\" aria-label=\"深度回归拟合\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">井点吻合<\/span><b id=\"roRmse\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">相关性<\/span><b id=\"roCorr\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"regTip\">绿色 = 井孔隙度真值，红色虚线 = 网络预测。拖「回归权重」模拟训练充分程度：权重越高，预测越贴近真值。井样本少，网络太深会过拟合——井点好但井间乱跳。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 多属性融合 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>振幅 / 频率 / 阻抗<\/b> 多属性自适应加权融合<span class=\"qa-algo\">深度回归 · 多属性融合<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 4<\/span>\n    <h2>多属性融合：单属性会失效，合起来才稳<\/h2>\n    <p class=\"leadline\">切三个属性的权重，看融合预测 RMSE 变化。单属性各有噪声与偏差，加权融合取长补短。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"fuseCtl\">\n    <div class=\"sl\">\n      <label>振幅权重<output id=\"outAmp\">0.50<\/output><\/label>\n      <input type=\"range\" id=\"inAmp\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.5\">\n    <\/div>\n    <div class=\"sl\">\n      <label>频率权重<output id=\"outFreq\">0.30<\/output><\/label>\n      <input type=\"range\" id=\"inFreq\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.3\">\n    <\/div>\n    <div class=\"sl\">\n      <label>阻抗权重<output id=\"outImp\">0.20<\/output><\/label>\n      <input type=\"range\" id=\"inImp\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.2\">\n    <\/div>\n  <\/div>\n  <svg id=\"fuseChart\" viewBox=\"0 0 470 280\" role=\"img\" aria-label=\"多属性融合预测\"><\/svg>\n  <div class=\"rrow ro1\">\n    <div class=\"ro\"><span class=\"k\">融合预测 RMSE<\/span><b id=\"roFuseRmse\" class=\"good\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"fuseTip\">绿色 = 真值，蓝色虚线 = 加权融合预测。单属性各有噪声与偏差，权重均衡一点、多属性融合，预测更稳；把某个属性权重拉到极端，融合预测会偏向那个有偏的属性。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 物理约束 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">回归输出 → <b>物理约束<\/b>（孔隙度范围 + 岩性一致）→ 可信孔隙度场<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5<\/span>\n    <h2>物理约束：把「看着合理但违反地质」的值校正回范围<\/h2>\n    <p class=\"leadline\">纯回归可能输出孔隙度为负、超范围的值。拖物理约束上限，看越界像素怎么被校正回可信范围。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"physCtl\">\n    <div class=\"sl\">\n      <label>孔隙度上限<output id=\"outHi\">0.35<\/output><\/label>\n      <input type=\"range\" id=\"inHi\" min=\"0.2\" max=\"0.45\" step=\"0.01\" value=\"0.35\">\n    <\/div>\n  <\/div>\n  <div class=\"fg\">\n    <div><svg id=\"physRaw\" viewBox=\"0 0 336 240\" role=\"img\" aria-label=\"原始孔隙度场\"><\/svg><div class=\"cap\">原始回归输出（红框 = 越界）<\/div><\/div>\n    <div><svg id=\"physCon\" viewBox=\"0 0 336 240\" role=\"img\" aria-label=\"物理约束后\"><\/svg><div class=\"cap\">物理约束后<\/div><\/div>\n  <\/div>\n  <div class=\"rrow ro1\">\n    <div class=\"ro\"><span class=\"k\">越界校正<\/span><b id=\"roOutRange\" class=\"good\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"physTip\">物理约束把超出范围的孔隙度校正回合理范围。约束太强会过度拉平细节，把真实的高孔隙度砂体也压平；太弱则不可信值漏网。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 3<\/b><br>深度回归，多属性 → 孔隙度。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>振幅/频率/阻抗自适应加权融合。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>物理约束校正不可信值。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：井震数据由「砂体孔隙 + 多属性」合成，孔隙度真值已知、仅供对比；深度回归、多属性融合与物理约束均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：地震属性怎么一步步变成孔隙度场',\n    stages: [\n      { name: '属性与对齐', tag: '井震对齐', dur: 4200, draw: function (t, g) { return F.stage1(t); } },\n      { name: '井点标签', tag: '回归标签', dur: 4400, draw: function (t, g) { return F.stage2(t); } },\n      { name: '深度回归', tag: '非线性映射', dur: 4800, draw: function (t, g) { return F.stage3(t); } },\n      { name: '多属性融合', tag: '自适应加权', dur: 4400, draw: function (t, g) { return F.stage4(t); } },\n      { name: '物理约束', tag: '范围+一致性', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '复核与部署', tag: '储层建模', dur: 4600, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的井震数据演示深度回归、多属性融合与物理约束。","height":600};
  var META = {"id":"s4-res-inversion","sceneId":"s4","title":"储层参数反演：深度回归 + 多属性融合 + 物理约束"};
  var handle = null;
  var DEF = {"id":"s4-res-inversion","sceneId":"s4","title":"储层参数反演：深度回归 + 多属性融合 + 物理约束","methods":["cv","opt"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"地震属性体 + 井参数","desc":"多属性 + 20—50 口井"},{"label":"标注成本","value":"中","desc":"井点孔隙度/饱和度/净毛比"},{"label":"可见收益","value":"快速代理反演","desc":"流程缩短、多解性收敛"},{"label":"难度","value":"中","desc":"井少 + 井震尺度不匹配 + 物理不可信"}],"lede":"从地震数据反演孔隙度、砂体厚度等储层参数，是把「反射同相轴」变成「储层模型」的关键一步。传统依赖稀疏井约束下的模型反演，流程长、多解性强、井少时结果偏离地质认识。智能方法用井震联合训练的深度网络建立「地震属性 → 储层参数」的非线性映射，作为快速代理反演。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>储层参数反演的第一步是把<b>「反射同相轴」<\/b>变成储层模型：从地震数据反演孔隙度、砂体厚度等参数，传统依赖稀疏井约束下的模型反演。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>流程长<\/b>——常规反演要标定、约束、迭代，一个工区要调很久参数<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>多解性强<\/b>——同样的地震数据可有多种参数组合，井少时结果偏离地质认识<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>难迁移<\/b>——每换一个工区都要重新标定、重新调参数<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"常规反演的流程长与多解性\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">常规反演：流程长 · 多解性 · 难迁移<\/text><rect x=\"20\" y=\"36\" width=\"186\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"113\" y=\"58\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">反演流程长<\/text><rect x=\"34\" y=\"72\" width=\"40\" height=\"30\" rx=\"4\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"54\" y=\"92\" text-anchor=\"middle\" font-size=\"8\" fill=\"#2b4a72\">标定<\/text><path d=\"M76 87 L92 87\" stroke=\"#9ba3a9\" stroke-width=\"1.4\"/><rect x=\"94\" y=\"72\" width=\"40\" height=\"30\" rx=\"4\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"114\" y=\"92\" text-anchor=\"middle\" font-size=\"8\" fill=\"#2b4a72\">约束<\/text><path d=\"M136 87 L152 87\" stroke=\"#9ba3a9\" stroke-width=\"1.4\"/><rect x=\"154\" y=\"72\" width=\"40\" height=\"30\" rx=\"4\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"174\" y=\"92\" text-anchor=\"middle\" font-size=\"8\" fill=\"#2b4a72\">迭代<\/text><text x=\"113\" y=\"126\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">一个工区调很久参数<\/text><text x=\"113\" y=\"190\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a6b52\">换工区要重新标定<\/text><text x=\"233\" y=\"66\" font-size=\"10\" fill=\"#4d565b\">同样地震数据<\/text><text x=\"233\" y=\"80\" font-size=\"10\" fill=\"#4d565b\">可有多种参数组合<\/text><text x=\"233\" y=\"150\" font-size=\"10\" fill=\"#4d565b\">井少（20—50 口）<\/text><text x=\"233\" y=\"164\" font-size=\"10\" fill=\"#4d565b\">约束不住多解性<\/text><text x=\"233\" y=\"180\" font-size=\"10\" fill=\"#b26a39\" font-weight=\"700\">结果偏离地质认识<\/text><path d=\"M222 120 C232 126 240 132 246 142\" fill=\"none\" stroke=\"#9ba3a9\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><rect x=\"270\" y=\"36\" width=\"330\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"435\" y=\"58\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">多解性：一个响应多种参数<\/text><path d=\"M300 100 C330 90 360 108 380 96\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.5\"/><text x=\"340\" y=\"86\" font-size=\"9\" fill=\"#4d565b\">地震响应<\/text><path d=\"M300 150 C330 160 360 144 380 156\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/><text x=\"340\" y=\"176\" font-size=\"9\" fill=\"#22604f\">孔隙度方案 A<\/text><path d=\"M300 190 C330 198 360 186 380 194\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/><text x=\"340\" y=\"212\" font-size=\"9\" fill=\"#8a4f27\">孔隙度方案 B<\/text><text x=\"520\" y=\"150\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a6b52\">A 与 B 都拟合地震响应<\/text><text x=\"520\" y=\"166\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a6b52\">但只有一个符合地质<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「迭代反演」换成「<b>深度回归代理<\/b>」：用井震联合训练的深度网络建立「地震属性 → 储层参数」的非线性映射，一次前向就得到孔隙度等参数，作为快速代理反演。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>深度回归<\/b>——网络把多属性映射到孔隙度连续值，替代迭代反演<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>多属性融合<\/b>——振幅、频率、阻抗等属性加权融合，捕捉不同尺度信息<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>物理约束损失<\/b>——把孔隙度范围、岩性一致性等物理先验加进损失，压制不可信结果<\/span><\/div><\/div><p>落地形态：反演流程从「周级迭代」压到「秒级前向」，多解性被物理约束收敛，井震尺度不匹配在特征层对齐。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"深度回归代理反演流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">深度回归代理：多属性 → 孔隙度（一次前向）<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">地震属性体<\/text><rect x=\"30\" y=\"72\" width=\"36\" height=\"30\" rx=\"3\" fill=\"#8aa7a7\"/><text x=\"80\" y=\"92\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#fff\" font-weight=\"700\">振幅<\/text><rect x=\"30\" y=\"106\" width=\"36\" height=\"30\" rx=\"3\" fill=\"#cbbf9a\"/><text x=\"80\" y=\"126\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#fff\" font-weight=\"700\">频率<\/text><rect x=\"68\" y=\"72\" width=\"36\" height=\"30\" rx=\"3\" fill=\"#9b86a8\"/><text x=\"120\" y=\"92\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#fff\" font-weight=\"700\">阻抗<\/text><rect x=\"68\" y=\"106\" width=\"36\" height=\"30\" rx=\"3\" fill=\"#a8bfd4\"/><text x=\"120\" y=\"126\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#fff\" font-weight=\"700\">... <\/text><text x=\"80\" y=\"176\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">多属性输入<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">深度回归网络<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">多属性融合<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">井震联合训练<\/text><text x=\"237\" y=\"118\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">物理约束损失<\/text><text x=\"237\" y=\"134\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">井点 20—50 口<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"394\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">孔隙度场<\/text><text x=\"394\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">连续值输出<\/text><text x=\"394\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">秒级一次前向<\/text><path d=\"M458 100 L482 100\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"486\" y=\"40\" width=\"114\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"543\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">地质复核<\/text><text x=\"543\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">井点吻合检查<\/text><text x=\"543\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">异常值复查<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">产出储层参数场 → 储层建模与井位优选<\/text><text x=\"310\" y=\"226\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">多解性被物理约束收敛 · 换工区只需少量井微调<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>地震属性体<\/b>：振幅、频率、阻抗等多属性，无需逐点标注；<b>测井解释参数<\/b>：井点孔隙度、饱和度、净毛比，20—50 口井；<b>地质模型<\/b>：沉积相与砂体展布，作为约束。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"储层参数反演数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">三类数据 + 约束策略<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">地震属性体<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">振幅、频率、阻抗等多属性<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">无需逐点标注<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">测井解释参数<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">井点孔隙度/饱和度/净毛比<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">20—50 口井<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">地质模型<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">沉积相与砂体展布<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">作为约束<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">物理先验<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">孔隙度范围、岩性一致性<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">加进损失函数<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">约束策略：井点 20—50 + 地质模型 + 物理约束损失 → 抑制不可信结果<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>井样本少<\/b>——只有 20—50 口井，深度回归容易过拟合<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>井震尺度不匹配<\/b>——测井是厘米级、地震是十米级，直接对齐会错位<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>物理不可信<\/b>——纯数据回归可能输出「看似合理但违反地质」的参数（孔隙度为负等）<\/span><\/div><\/div><p>改进路线按成本从低到高：先<b>多属性融合 + 深度回归<\/b>把基线做出来，建立非线性映射；再加<b>物理约束损失<\/b>（孔隙度范围、岩性一致性）压制不可信结果；最后在<b>特征层对齐井震尺度<\/b>，并用<b>少量井微调<\/b>跨工区迁移。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"储层反演难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 井样本少<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">20—50 口井易过拟合<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">多属性融合 + 深度回归<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">建立非线性映射<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 井震尺度不匹配<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">测井厘米级·地震十米级<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">特征层对齐尺度<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">井震在特征层对齐<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 物理不可信<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">纯回归输出违反地质参数<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">物理约束损失<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">范围+一致性压制<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">多属性融合基线 → 物理约束损失 → 特征层对齐 + 少量井微调<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一个工区的储层参数反演改造","lead":["某工区有 35 口井，此前用常规模型反演反演孔隙度，流程长、多解性强。目标：用深度回归代理把「多属性 → 孔隙度」建出来，加物理约束收敛多解性，秒级出孔隙度场。","注意第 3、4、5 步：深度回归、多属性融合、物理约束是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["工区","某三维工区"],["井数","35 口"],["地震属性","振幅/频率/阻抗"],["目标参数","孔隙度/砂厚"],["目标时间","秒级前向"],["物理约束","范围+一致性"]],"steps":[{"name":"属性提取与井震对齐","role":"数据","do":"从地震体提取振幅、频率、阻抗等多属性；把井点测井参数沿井轨迹投影到地震网格，与属性对齐。示范页屏 1 顶部可切换属性通道看不同属性对孔隙度的区分度。","effect":"一张与井点参数对齐的多属性体，作为回归输入。","trap":"井震尺度不匹配（测井厘米级 vs 地震十米级）直接对齐会错位，模型学到错位的假映射。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据接入：属性提取 → 井震对齐<\/text><rect x=\"24\" y=\"42\" width=\"140\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"94\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">地震体 → 多属性<\/text><text x=\"94\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">振幅/频率/阻抗<\/text><path d=\"M168 68 L190 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"194\" y=\"42\" width=\"180\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"284\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">井点参数投影<\/text><text x=\"284\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">沿井轨迹对齐网格<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">对齐的多属性体<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">含井点真值<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：井震尺度不匹配直接对齐 → 错位 → 模型学到假映射<\/text><\/svg>"},{"name":"井点标签构建","role":"标注","do":"把井点测井解释的孔隙度、饱和度、净毛比整理成回归标签；留出独立验证井。示范页屏 1 顶部可切换井数看稀疏程度对回归的影响。","effect":"有可训练、可复现评测的井点参数标签，锚定孔隙度范围。","trap":"井标签带解释误差，直接把误差学进映射，井点预测会偏离真值。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">标签构建：测井参数 → 回归标签 + 验证井<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">测井解释参数<\/text><text x=\"99\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">孔隙度/饱和度<\/text><path d=\"M178 68 L202 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"180\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"296\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">回归标签<\/text><text x=\"296\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">连续值真值<\/text><path d=\"M390 68 L414 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"418\" y=\"42\" width=\"176\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"506\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">留验证井<\/text><text x=\"506\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">独立评测口径<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：井标签带解释误差 → 模型把误差学进映射 → 井点预测偏离<\/text><\/svg>"},{"name":"深度回归映射","role":"算法核心","do":"用深度网络建立「多属性 → 孔隙度」的非线性映射，替代迭代反演；损失用回归损失。示范页屏 1 在浏览器里实时跑一个小型回归演示。","effect":"一个可秒级前向的孔隙度预测器，井点吻合、全数据体出图。","trap":"网络太深井样本少会过拟合，井点拟合好但井间乱跳；需要正则与交叉验证。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">深度回归：多属性 → 孔隙度<\/text><rect x=\"24\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"89\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">多属性向量<\/text><text x=\"89\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">振幅/频率/阻抗<\/text><path d=\"M170 77 L200 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"204\" y=\"42\" width=\"140\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"274\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">深度回归网络<\/text><text x=\"274\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">非线性映射<\/text><path d=\"M348 77 L378 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"382\" y=\"42\" width=\"210\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"487\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">孔隙度预测<\/text><text x=\"487\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">连续值 · 秒级前向<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：网络太深井样本少 → 过拟合 → 井点好但井间乱跳，需正则<\/text><\/svg>"},{"name":"多属性融合","role":"算法核心","do":"把振幅、频率、阻抗等属性加权融合成特征；不同属性捕捉不同尺度信息，融合后对孔隙度更稳健。示范页屏 2 展示不同属性对孔隙度的贡献权重。","effect":"综合多属性信息的孔隙度预测，单属性失效时仍能靠其它属性兜底。","trap":"简单拼接而不学习权重，噪声属性反而拉低精度；需自适应加权。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">多属性融合：加权 → 特征 → 孔隙度<\/text><rect x=\"24\" y=\"42\" width=\"90\" height=\"50\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"69\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">振幅<\/text><text x=\"69\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">权重 0.5<\/text><rect x=\"24\" y=\"96\" width=\"90\" height=\"40\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"69\" y=\"114\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">频率<\/text><text x=\"69\" y=\"128\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">权重 0.3<\/text><rect x=\"118\" y=\"70\" width=\"40\" height=\"40\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"138\" y=\"92\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">阻抗<\/text><path d=\"M162 90 L190 90\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"194\" y=\"42\" width=\"130\" height=\"100\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"259\" y=\"80\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">融合特征<\/text><text x=\"259\" y=\"98\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">自适应加权<\/text><path d=\"M328 92 L358 92\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"362\" y=\"42\" width=\"230\" height=\"100\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"477\" y=\"80\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">孔隙度预测<\/text><text x=\"477\" y=\"98\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">单属性失效仍能兜底<\/text><text x=\"24\" y=\"140\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：简单拼接不学权重 → 噪声属性拉低精度，需自适应加权<\/text><\/svg>"},{"name":"物理约束损失","role":"工程环节","do":"把孔隙度范围、岩性一致性等物理先验加进损失；输出超出物理范围的值被惩罚。示范页屏 3 展示加物理约束前后孔隙度场的差异。","effect":"抑制「看起来合理但违反地质」的结果，孔隙度场符合物理。","trap":"物理约束太强会过度拉平细节，把真实的高孔隙度砂体也压平。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">物理约束：范围 + 一致性 → 惩罚不可信<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">回归输出<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">可能为负/超物理范围<\/text><path d=\"M188 77 L212 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"216\" y=\"42\" width=\"160\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"296\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">物理约束损失<\/text><text x=\"296\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">范围 + 岩性一致性<\/text><path d=\"M380 77 L404 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">可信孔隙度场<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">符合物理范围<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：物理约束太强 → 过度拉平细节 → 真实高孔隙度砂体被压平<\/text><\/svg>"},{"name":"地质复核与井位部署","role":"人工确认","do":"地质师对井点吻合、异常值复查；孔隙度场进入储层建模与井位部署；错误反馈回训练集。示范页屏 3 展示按异常值分层的复核清单。","effect":"孔隙度场可信、可追溯，人只处理异常区，错误持续回流改进模型。","trap":"没有人在环，物理上不可信的孔隙度场直接进储层建模，会在井位部署里扩散。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">复核：井点吻合 → 异常复查 → 储层建模 + 回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">井点吻合检查<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">独立验证井<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">异常值复查<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">物理不可信区<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">储层建模 + 回流<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">井位部署 + 错误回流<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：无人在环 → 不可信孔隙度场直接进储层建模 → 井位部署扩散<\/text><\/svg>"}],"metrics":{"title":"怎么算「反演对了」","html":"<p>深度回归用 <b>井点吻合度<\/b>（预测孔隙度 vs 测井孔隙度）验收，用 <b>RMSE / 相关系数<\/b> 量化；同时检查 <b>物理可信性<\/b>——孔隙度是否落在合理范围、有无违反岩性一致性的异常。<\/p><p>最终还要看 <b>储层建模可用性<\/b>：孔隙度场与井点吻合、与地质认识一致，而非仅在井上好看、井间乱跳。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='储层反演效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>反演验收：井点吻合 × 物理可信<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>井点吻合（RMSE）<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>RMSE 2.1<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>常规反演<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>RMSE 1.2<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>深度回归<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>井点预测孔隙度 vs 测井孔隙度<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>物理可信性<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>孔隙度在范围<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>无负值/无超界<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>岩性一致<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>砂体展布合理<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>仅井上好看、井间乱跳不算数<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 井点 RMSE × 物理可信 × 储层建模可用性<\/text><\/svg><\/p>"},"fails":[{"name":"井样本少过拟合","why":"只有 20—50 口井，深度回归容易过拟合，井点拟合好但井间乱跳。"},{"name":"井震尺度错位","why":"测井厘米级、地震十米级，直接对齐会错位，模型学到错位的假映射。"},{"name":"物理不可信","why":"纯数据回归可能输出「看似合理但违反地质」的参数（孔隙度为负等），必须物理约束。"},{"name":"约束过度拉平","why":"物理约束太强会过度拉平细节，把真实的高孔隙度砂体也压平。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的井震数据演示深度回归、多属性融合与物理约束。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
